import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const host=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15; host.appendChild(renderer.domElement);
const scene=new THREE.Scene(); scene.background=new THREE.Color('#a9a18b'); scene.fog=new THREE.Fog('#a9a18b',48,100);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,150); camera.position.set(0,29,34); camera.lookAt(0,0,0);
scene.add(new THREE.HemisphereLight('#e7e2cf','#4f5941',2)); const sun=new THREE.DirectionalLight('#ffe3b0',3); sun.position.set(-14,28,12); sun.castShadow=true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-35;sun.shadow.camera.right=35;sun.shadow.camera.top=30;sun.shadow.camera.bottom=-30; scene.add(sun);
const mat=(color,roughness=.9)=>new THREE.MeshStandardMaterial({color,roughness});
const mats={grass:mat('#66764f'),grass2:mat('#74845a'),dirt:mat('#a18a62'),wood:mat('#594231'),roof:mat('#54443b'),roof2:mat('#685141'),wall:mat('#d1bd94'),red:mat('#9c4037'),blue:mat('#394d54'),black:mat('#242729'),skin:mat('#d4a47d'),gold:mat('#cba761'),leaf:mat('#536b46'),pink:mat('#bd7774'),stone:mat('#777365')};
const ground=new THREE.Mesh(new THREE.PlaneGeometry(90,80),mats.grass); ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
const grid=new THREE.GridHelper(80,40,'#8e9770','#8e9770');grid.position.y=-.105;grid.material.transparent=true;grid.material.opacity=.13;scene.add(grid);
function box(parent,x,y,z,w,h,d,material,rx=0,ry=0,rz=0){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.rotation.set(rx,ry,rz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cyl(parent,x,y,z,r1,r2,h,material,seg=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,seg),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,x,y,z,r,material){const m=new THREE.Mesh(new THREE.SphereGeometry(r,10,8),material);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
// Winding earth path and stream
const path=new THREE.Mesh(new THREE.PlaneGeometry(8,50),mats.dirt);path.rotation.x=-Math.PI/2;path.rotation.z=-.12;path.position.set(1,-.09,0);scene.add(path);
const creek=new THREE.Mesh(new THREE.PlaneGeometry(5,48),mat('#586e70'));creek.rotation.x=-Math.PI/2;creek.rotation.z=.08;creek.position.set(-20,-.08,-1);scene.add(creek);
for(let i=0;i<34;i++){let x=-22+Math.random()*5,z=-23+Math.random()*46;let r=.15+Math.random()*.35;let rock=sphere(scene,x,.02,z,r,mats.stone);rock.scale.y=.5;}
// A tiny feudal hamlet
function hut(x,z,s=1){let g=new THREE.Group();g.position.set(x,0,z);scene.add(g);box(g,0,.7,0,2.4*s,1.4*s,2*s,mats.wall);box(g,0,.12,0,2.65*s,.22*s,2.25*s,mats.wood);let roof= new THREE.Mesh(new THREE.ConeGeometry(1.95*s,.9*s,4),mats.roof);roof.rotation.y=Math.PI/4;roof.position.y=1.75*s;roof.scale.set(1.1,1,1);roof.castShadow=true;g.add(roof);box(g,0,.42,1.01*s,.48*s,.82*s,.08,mats.wood);box(g,-.65*s,1.06*s,1.02*s,.25*s,.07,.07,mats.wood);box(g,.65*s,1.06*s,1.02*s,.25*s,.07,.07,mats.wood);return g}
hut(-5,-7,1.1);hut(5,-9,.9);hut(-7,1,.85);hut(7,3,1);hut(0,10,1.15);
// banners and village fence
for(let j=0;j<2;j++){let x=j?9:-9;for(let z=-9;z<12;z+=1.2){if(Math.abs(z+7)<2||Math.abs(z-1)<2||Math.abs(z-9)<2)continue;box(scene,x,.38,z,.12,.76,.12,mats.wood);if(Math.round(z)%3===0)box(scene,x,.58,z,.13,.1,1.15,mats.wood);}}
function tree(x,z,pink=false){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);cyl(g,0,.95,0,.19,.28,1.9,mats.wood,7);for(let i=0;i<3;i++){let r=1.05-i*.13;let crown=new THREE.Mesh(new THREE.IcosahedronGeometry(r,1),pink?mats.pink:mats.leaf);crown.position.set((i%2-.5)*.24,1.7+i*.55,0);crown.castShadow=true;g.add(crown);}return g}
for(const p of [[-13,-15],[13,-16],[-13,-5],[13,-5],[-14,7],[14,9],[-11,17],[11,17],[3,-17],[-2,17]])tree(...p,p[0]<0&&p[1]===-15);
// rocks, lanterns and a shrine gate
for(let i=0;i<16;i++){let x=(Math.random()-.5)*31,z=(Math.random()-.5)*38;if(Math.abs(x)<10&&Math.abs(z)<14)continue;let r=.3+Math.random()*.5;let o=sphere(scene,x,r*.4,z,r,mats.stone);o.scale.y=.65;}
const gate=new THREE.Group();gate.position.set(0,0,-13);scene.add(gate);for(const x of [-2,2]){box(gate,x,1.5,0,.28,3,.3,mats.red);box(gate,x,2.85,0,.48,.2,.48,mats.black);}box(gate,0,3.05,0,5,.3,.48,mats.red);box(gate,0,3.34,0,5.6,.18,.65,mats.black);for(let i=-2;i<=2;i++)box(gate,i,2.0,.04,.65,.1,.1,mats.gold);
// Unit models: clear colors and readable silhouettes
const units=[];let selected=null;let resources={food:180,gold:120};let kills=0,day=1,gameStarted=false,gameEnded=false,commandMode='';const hitables=[];
function makeUnit(team,kind,x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const isNinja=kind==='shinobi',friendly=team==='ally';const cloth=friendly?(isNinja?mats.black:mats.blue):(isNinja?mats.black:mats.red);const body=cyl(g,0,.73,0,.34,.43,.85,cloth,8);body.rotation.z=-.06;box(g,0,.77,.33,.48,.12,.12,friendly?mats.gold:mats.red,0,0,-.12);sphere(g,0,1.35,0,.28,mats.skin);let helm=cyl(g,0,1.58,0,.37,.09,.22,friendly?mats.blue:mats.red,8);if(isNinja){box(g,0,1.36,.27,.39,.17,.1,mats.black);box(g,0,1.22,.3,.31,.06,.12,mats.black);}else{let h=cyl(g,0,1.72,0,.43,.15,.13,cloth,8);h.scale.z=.8;box(g,0,1.88,0,.06,.34,.07,mats.gold);}
// sword on the hip
box(g,.44,.74,.08,.08,.67,.09,mats.black,0,0,-.4);let blade=box(g,.44,.84,.12,.035,.47,.035,mat(friendly?'#d9d4c3':'#d9c9b3'),0,0,-.4);
const ring=new THREE.Mesh(new THREE.RingGeometry(.48,.62,24),new THREE.MeshBasicMaterial({color:friendly?0xe1bd78:0xb9473b,side:THREE.DoubleSide,transparent:true,opacity:.8}));ring.rotation.x=-Math.PI/2;ring.position.y=.04;g.add(ring);
const healthbg=new THREE.Mesh(new THREE.PlaneGeometry(.9,.09),new THREE.MeshBasicMaterial({color:0x201c1a,side:THREE.DoubleSide}));healthbg.position.set(0,2.12,0);g.add(healthbg);const healthfg=new THREE.Mesh(new THREE.PlaneGeometry(.86,.055),new THREE.MeshBasicMaterial({color:friendly?0x8fc47b:0xc95145,side:THREE.DoubleSide}));healthfg.position.set(0,2.13,.01);g.add(healthfg);
const u={group:g,team,kind,hp:100,maxHp:100,attackTimer:Math.random()*.5,target:null,moveTarget:null,speed:isNinja?3.5:2.55,healthfg,healthbg,ring,dead:false};g.userData.unit=u;g.traverse(o=>{if(o.isMesh)hitables.push(o)});units.push(u);return u;}
makeUnit('ally','samurai',-2,2);makeUnit('ally','samurai',2,3);makeUnit('ally','shinobi',0,5);makeUnit('enemy','samurai',-1,-21);makeUnit('enemy','samurai',3,-23);makeUnit('enemy','shinobi',-4,-24);

