makeUnit('ally','samurai',-2,2);makeUnit('ally','samurai',2,3);makeUnit('ally','shinobi',0,5);makeUnit('enemy','samurai',-1,-21);makeUnit('enemy','samurai',3,-23);makeUnit('enemy','shinobi',-4,-24);
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();const groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0),point=new THREE.Vector3();
const $=s=>document.querySelector(s);function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2100)}
function refreshHUD(){ $('#food').textContent=resources.food;$('#gold').textContent=resources.gold;$('#army').textContent=units.filter(u=>u.team==='ally'&&!u.dead).length;$('#count').textContent=`${kills} / 6`;$('#progress').style.width=`${Math.min(100,kills/6*100)}%`;$('#recruitSamurai').disabled=resources.food<60;$('#recruitNinja').disabled=resources.gold<45; }
function setSelection(u){if(selected)selected.ring.material.opacity=.8;selected=u;if(u){u.ring.material.opacity=1;$('#selTitle').textContent=(u.team==='enemy'?'Enemy ':'')+(u.kind==='shinobi'?'Shinobi':'Samurai');$('#selSub').textContent=`${u.team==='ally'?'Your warrior':'Hostile raider'} · ${Math.ceil(u.hp)}% strength`;$('#portrait').textContent=u.kind==='shinobi'?'☯':'⛩';}else{$('#selTitle').textContent='Village Guard';$('#selSub').textContent='Select a unit to command';$('#portrait').textContent='⛩';}}
function worldAt(clientX,clientY){pointer.x=clientX/innerWidth*2-1;pointer.y=-(clientY/innerHeight)*2+1;raycaster.setFromCamera(pointer,camera);raycaster.ray.intersectPlane(groundPlane,point);return point.clone()}
function unitAt(clientX,clientY){pointer.x=clientX/innerWidth*2-1;pointer.y=-(clientY/innerHeight)*2+1;raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(hitables,false);for(const h of hits){let o=h.object;while(o&&!o.userData.unit)o=o.parent;if(o)return o.userData.unit;}return null;}
let pointerDown=0;renderer.domElement.addEventListener('pointerdown',e=>{pointerDown=performance.now();});renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());renderer.domElement.addEventListener('pointerup',e=>{if(!gameStarted||gameEnded||performance.now()-pointerDown>550)return;const u=unitAt(e.clientX,e.clientY);if(e.button===2){if(selected&&selected.team==='ally'){const p=worldAt(e.clientX,e.clientY);selected.moveTarget=p;selected.target=null;}return;}if(u){if(u.team==='ally'){setSelection(u);commandMode='';$('.command.active')?.classList.remove('active');}else if(selected?.team==='ally'){selected.target=u;selected.moveTarget=null;toast('Attack target marked');}else setSelection(u);}else{const p=worldAt(e.clientX,e.clientY);if(commandMode==='move'&&selected?.team==='ally'){selected.moveTarget=p;selected.target=null;}else if(commandMode==='attack'&&selected?.team==='ally'){const enemy=units.filter(v=>v.team==='enemy'&&!v.dead).sort((a,b)=>a.group.position.distanceTo(p)-b.group.position.distanceTo(p))[0];if(enemy){selected.target=enemy;selected.moveTarget=null;}}else if(selected?.team==='ally'){selected.moveTarget=p;selected.target=null;}else setSelection(null);}});
function activateMode(mode){if(!selected||selected.team!=='ally'){toast('Select one of your warriors first');return;}commandMode=mode;$('.command.active')?.classList.remove('active');if(mode!=='')$(`#${mode}Cmd`).classList.add('active');toast(mode==='move'?'Click the ground to move':'Click an enemy to attack');}
$('#moveCmd').onclick=()=>activateMode('move');$('#attackCmd').onclick=()=>activateMode('attack');$('#stopCmd').onclick=()=>{if(selected){selected.target=null;selected.moveTarget=null;toast('Warrior standing down');}};
document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='m')activateMode('move');if(e.key.toLowerCase()==='a')activateMode('attack');if(e.key.toLowerCase()==='s'&&selected){selected.target=null;selected.moveTarget=null;}if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))keys.add(e.key.toLowerCase());});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));const keys=new Set();
$('#recruitSamurai').onclick=()=>{if(resources.food<60)return;resources.food-=60;let x=-2+Math.random()*4,z=8+Math.random()*2;setSelection(makeUnit('ally','samurai',x,z));toast('A samurai answers your call');refreshHUD();};$('#recruitNinja').onclick=()=>{if(resources.gold<45)return;resources.gold-=45;let x=-2+Math.random()*4,z=8+Math.random()*2;setSelection(makeUnit('ally','shinobi',x,z));toast('A shinobi emerges from the shadows');refreshHUD();};let lastGather=0;$('#gather').onclick=()=>{const now=performance.now();if(now-lastGather<6500){toast('The village needs time to harvest');return;}lastGather=now;resources.food+=35;resources.gold+=15;refreshHUD();toast('Villagers bring in +35 rice and +15 mon');};
$('#start').onclick=()=>{$('#intro').classList.add('hidden');gameStarted=true;toast('Scouts approaching from the north!');};
