input.newString:
function tick(dt){
 if(!gameStarted||gameEnded)return;
 elapsed+=dt;waveClock+=dt;
 if(waveClock>24){waveClock=0;spawnWave();}
 const living=units.filter(u=>!u.dead);
 for(const u of living){
  if(u.dead)continue;
  u.attackTimer-=dt;
  let target=u.target;
  if(target?.dead){u.target=null;target=null;}
  if(!target){
   const range=u.team==='enemy'?8:5;
   const candidates=living.filter(v=>!v.dead&&v.team!==u.team&&v.group.position.distanceTo(u.group.position)<range);
   if(candidates.length){target=candidates.sort((a,b)=>a.group.position.distanceTo(u.group.position)-b.group.position.distanceTo(u.group.position))[0];u.target=target;}
  }
  if(u.team==='enemy'&&!target){
   const allies=living.filter(v=>!v.dead&&v.team==='ally');
   const nearest=allies.sort((a,b)=>a.group.position.distanceTo(u.group.position)-b.group.position.distanceTo(u.group.position))[0];
   if(nearest&&nearest.group.position.distanceTo(u.group.position)<7)target=u.target=nearest;
   else if(!u.moveTarget)u.moveTarget=new THREE.Vector3((Math.random()-.5)*5,0,9);
  }
  if(target){
   const delta=target.group.position.clone().sub(u.group.position);delta.y=0;
   const dist=delta.length();
   if(dist>1.55){delta.normalize();u.group.position.addScaledVector(delta,u.speed*dt);u.group.rotation.y=Math.atan2(delta.x,delta.z);}
   else if(u.attackTimer<=0){
    damage(target,u.team==='enemy'?(u.kind==='shinobi'?10:9):(u.kind==='shinobi'?22:18));
    u.attackTimer=u.team==='enemy'?(u.kind==='shinobi'?1:1.15):(u.kind==='shinobi'?.68:.88);
   }
  }else if(u.moveTarget){
   const delta=u.moveTarget.clone().sub(u.group.position);delta.y=0;
   if(delta.length()<.45)u.moveTarget=null;
   else{delta.normalize();u.group.position.addScaledVector(delta,u.speed*dt);u.group.rotation.y=Math.atan2(delta.x,delta.z);}
  }
  u.group.position.x=THREE.MathUtils.clamp(u.group.position.x,-19,19);
  u.group.position.z=THREE.MathUtils.clamp(u.group.position.z,-26,24);
  u.healthbg.quaternion.copy(camera.quaternion);u.healthfg.quaternion.copy(camera.quaternion);u.ring.rotation.z=0;
 }
 if(selected?.dead)setSelection(null);
 if(selected&&!selected.dead)$('#selSub').textContent=`${selected.team==='ally'?'Your warrior':'Hostile raider'} · ${Math.ceil(selected.hp)}% strength`;
}

